<?php
declare(strict_types=1);

return static function (PDO $pdo): void {
    $pdo->exec("CREATE TABLE IF NOT EXISTS online_tests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,instructions TEXT NULL,opens_at DATETIME NULL,closes_at DATETIME NULL,duration_minutes SMALLINT UNSIGNED NULL,status ENUM('draft','published','closed') NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_online_tests_class(class_id,status),CONSTRAINT fk_online_tests_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_online_tests_class FOREIGN KEY(class_id) REFERENCES classes(id),CONSTRAINT fk_online_tests_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS online_test_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id BIGINT UNSIGNED NOT NULL,question_type ENUM('mcq','written') NOT NULL,question_text TEXT NOT NULL,marks DECIMAL(8,2) NOT NULL,position SMALLINT UNSIGNED NOT NULL,options_json TEXT NULL,correct_option SMALLINT UNSIGNED NULL,CONSTRAINT fk_online_questions_test FOREIGN KEY(test_id) REFERENCES online_tests(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS online_test_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status ENUM('in_progress','submitted','marked') NOT NULL DEFAULT 'in_progress',started_at DATETIME NOT NULL,submitted_at DATETIME NULL,marked_at DATETIME NULL,marked_by BIGINT UNSIGNED NULL,total_score DECIMAL(8,2) NULL,UNIQUE KEY uq_online_attempt(test_id,student_id),CONSTRAINT fk_online_attempt_test FOREIGN KEY(test_id) REFERENCES online_tests(id) ON DELETE CASCADE,CONSTRAINT fk_online_attempt_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,CONSTRAINT fk_online_attempt_marker FOREIGN KEY(marked_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS online_test_answers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,answer_text TEXT NULL,selected_option SMALLINT UNSIGNED NULL,score DECIMAL(8,2) NULL,feedback TEXT NULL,UNIQUE KEY uq_online_answer(attempt_id,question_id),CONSTRAINT fk_online_answer_attempt FOREIGN KEY(attempt_id) REFERENCES online_test_attempts(id) ON DELETE CASCADE,CONSTRAINT fk_online_answer_question FOREIGN KEY(question_id) REFERENCES online_test_questions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $now=date('Y-m-d H:i:s');
    $stmt=$pdo->prepare('INSERT IGNORE INTO permissions(name,slug,created_at,updated_at) VALUES(?,?,?,?)');
    $stmt->execute(['Manage online student tests','online-tests.manage',$now,$now]);
};
